scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_3'] || []

control 'CKV_AWS_3' do
  title 'Ensure all data stored in the EBS is securely encrypted'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_ebs_volume resources that actually exist, read through the stock
    inspec-aws aws_ebs_volume resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Ensure all data stored in the EBS is securely encrypted. Anchors derived
    from the check's encryption category, not reviewed control by control.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_ebs_volume: encrypted is True
